<main class="gc-interior"><section class="gc-profile-hero gc-dark"><div class="gc-container gc-profile-grid"><div class="gc-profile-photo"><?php if(has_post_thumbnail()){the_post_thumbnail('gc-avatar');}else{?><span>GC</span><?php }?></div><div><span class="gc-kicker">Game Changer profile</span><h1><?php the_title();?></h1><p class="gc-profile-role"><?php echo esc_html(gc_member_field($id,'gc_member_job_title',gc_member_field($id,'gc_member_profession','Game Changer')));?></p><?php if($chapter){?><span class="gc-profile-chip"><?php echo esc_html(get_the_title($chapter));?></span><?php } if($cohort){?><span class="gc-profile-chip">Cohort <?php echo esc_html(get_post_meta($cohort,'gc_cohort_number',true)?:get_the_title($cohort));?></span><?php }?></div></div></section><section class="gc-section"><div class="gc-container gc-profile-content"><div><span class="gc-kicker gc-kicker-green">About</span><h2>Leadership in <em>action.</em></h2><p><?php echo esc_html($bio?:get_the_excerpt());?></p><?php if($chapter){?><h3>Chapter</h3><p><a class="gc-text-link" href="<?php echo esc_url(get_permalink($chapter));?>"><?php echo esc_html(get_the_title($chapter));?></a></p><?php }?></div><aside><h3>Leadership focus</h3><p><?php echo esc_html(gc_member_field($id,'gc_member_leadership_focus','Community leadership'));?></p><h3>Skills</h3><p><?php echo esc_html(gc_member_field($id,'gc_member_skills','Leadership, collaboration, service'));?></p></aside></div></section></main><?php get_footer(); ?>
